<script setup lang="ts">
import type { MapState, MapFeature, GeoShape, CommunityRecord, UseData } from '~/types/community'
import type { PointDto, PointDetailDto } from '~/types/api'
import { errorMessage } from '~/utils/format'
const { bootstrap, load: loadBootstrap } = useAppData()
const { purposes, purpose, loadPurposes } = usePurposeCatalog()
const mapState=ref<MapState>({layers:[],features:[]}),error=ref(''),query=ref(''),loading=ref(false)
const selected=ref<MapFeature|null>(null),detail=ref<PointDetailDto|null>(null),uses=ref<CommunityRecord<UseData>[]>([])
const useId=ref(''),useOpen=ref(false),inspectionId=ref(''),mobilePane=ref('place'),showEnded=ref(false)
const pending=ref<GeoShape|null>(null),saving=ref(false),editor=ref(false),editingPoint=ref<PointDto|null>(null),gridId=ref(''),filterOpen=ref(false),searchResults=ref(false)
const filter=reactive({grid:'all',type:'all',purpose:'all',issues:false,grids:true})
const canvas=useTemplateRef('canvas')
const currentUse=computed(()=>uses.value.find(x=>x.id===useId.value)??null)
const shownUses=computed(()=>uses.value.filter(x=>showEnded.value||(!x.archived&&x.data.state!=='已结束')))
const pendingCoordinates=computed(()=>pending.value?.coordinates[0]?.join(',')??'')
const grids=computed(()=>[{label:'全部网格',value:'all'},...(bootstrap.value?.communities??[]).map(x=>({label:x.name,value:x.id}))])
const types=computed(()=>[{label:'全部场所形态',value:'all'},...(bootstrap.value?.pointTypes??[]).map(x=>({label:x.name,value:x.id}))])
const purposeOptions=computed(()=>[{label:'全部用途',value:'all'},...purposes.value.filter(x=>!x.archived).map(x=>({label:`${x.data.icon} ${x.name}`,value:x.id}))])
const filtered=computed(()=>mapState.value.features.filter(x=>!x.disabled&&(x.kind==='grid'?filter.grids:(filter.grid==='all'||x.communityId===filter.grid)&&(filter.type==='all'||x.typeId===filter.type)&&(filter.purpose==='all'||x.purposeIds?.includes(filter.purpose))&&(!filter.issues||x.openIssues>0))).filter(x=>!query.value||x.name.includes(query.value)).map(x=>filter.purpose!=='all'&&x.kind==='point'?{...x,icon:purpose(filter.purpose)?.data.icon||x.icon}:x))
const matches=computed(()=>filtered.value.filter(x=>x.kind==='point'))
const focusPadding=computed(()=>typeof window!=='undefined'&&window.innerWidth>=1100?[90,60,60,Math.min(window.innerWidth*.42,430)]:[120,40,100,40])
let selectionSequence=0
async function load(){loading.value=true;try{await Promise.all([loadBootstrap(),loadPurposes()]);mapState.value=await $fetch('/api/map')}catch(e){error.value=errorMessage(e)}finally{loading.value=false}}
async function choose(item:MapFeature,focus=true){const request=++selectionSequence;searchResults.value=false;filterOpen.value=false;selected.value=item;detail.value=null;uses.value=[];useOpen.value=false;inspectionId.value='';mobilePane.value='place';error.value='';if(focus)canvas.value?.focus(item.shape);if(item.kind!=='point')return;try{const [place,records]=await Promise.all([$fetch<PointDetailDto>(`/api/points/${item.id}`),$fetch<CommunityRecord<UseData>[]>('/api/records/use',{query:{parentId:item.id,all:true}})]);if(request!==selectionSequence)return;detail.value=place;uses.value=records;const active=records.filter(x=>!x.archived&&x.data.state!=='已结束');if(active.length===1){useId.value=active[0]!.id;useOpen.value=true}}catch(e){if(request===selectionSequence)error.value=errorMessage(e)}}
function closePlace(){++selectionSequence;selected.value=null;detail.value=null;useOpen.value=false;inspectionId.value=''}
function openUse(record:CommunityRecord<UseData>|null){useId.value=record?.id??'';useOpen.value=true;mobilePane.value='use'}
async function useSaved(record:CommunityRecord<UseData>){if(!selected.value)return;const feature=selected.value;await load();await choose(mapState.value.features.find(x=>x.id===feature.id&&x.kind==='point')??feature,false);useId.value=record.id;useOpen.value=true;mobilePane.value='use'}
async function refreshed(){if(!selected.value)return;const feature=selected.value;const check=inspectionId.value;await load();await choose(mapState.value.features.find(x=>x.id===feature.id)??feature,false);inspectionId.value=check;mobilePane.value='inspection'}
async function saveShape(kind:string,id:string,revision:number){if(!pending.value)return;saving.value=true;error.value='';try{await $fetch(`/api/map/shapes/${kind}/${id}`,{method:'PUT',body:{shape:pending.value,revision},retry:0});canvas.value?.cancel();await load();const feature=mapState.value.features.find(x=>x.kind===kind&&x.id===id);if(feature)await choose(feature,false)}catch(e){error.value=errorMessage(e)}finally{saving.value=false}}
function newPlace(){editingPoint.value=null;editor.value=true}
async function created(point:PointDto){canvas.value?.cancel();await load();const feature=mapState.value.features.find(x=>x.kind==='point'&&x.id===point.id);if(feature)await choose(feature)}
function editShape(){if(selected.value){canvas.value?.edit(selected.value.shape);useOpen.value=false;inspectionId.value=''}}
onMounted(load)
useHead({title:'社区地图'})
</script>
<template>
  <div class="community-map" data-testid="map-workspace">
    <OfflineMap ref="canvas" v-model="pending" :features="filtered" :layers="mapState.layers" :selected-id="selected?.id" :focus-padding="focusPadding" immersive height="100%" @choose="choose" />
    <div class="map-search floating"><div class="flex gap-2"><UInput v-model="query" @update:model-value="searchResults=true" placeholder="搜索场所名称" icon="i-lucide-search" class="min-w-0 flex-1" /><UButton icon="i-lucide-list-filter" aria-label="筛选地图" color="neutral" :variant="filterOpen?'solid':'outline'" @click="filterOpen=!filterOpen" /></div><div v-if="filterOpen" class="space-y-2 mt-3"><USelect v-model="filter.grid" :items="grids" class="w-full" /><USelect v-model="filter.type" :items="types" class="w-full" /><USelect v-model="filter.purpose" :items="purposeOptions" class="w-full" /><div class="flex flex-wrap gap-4"><UCheckbox v-model="filter.issues" label="仅有未完成问题" /><UCheckbox v-model="filter.grids" label="显示网格边界" /></div><div class="flex justify-between text-sm text-muted"><span>{{ matches.length }} 个场所</span><button @click="Object.assign(filter,{grid:'all',type:'all',purpose:'all',issues:false,grids:true});query=''">清空筛选</button></div></div><div v-if="query && searchResults" class="map-search-results"><button v-for="item in matches.slice(0,20)" :key="item.id" @click="choose(item)">{{ item.icon }} {{ item.name }}</button><p v-if="!matches.length" class="p-2 text-muted">没有匹配场所</p></div></div>
    <UAlert v-if="error" :description="error" color="error" class="map-error" closable @update:open="value=>{if(!value)error=''}" />
    <div v-if="pending" class="map-save floating"><strong>{{ pending.type==='Point'?'已标记位置':`已画 ${pending.type==='MultiPolygon'?pending.areas?.length:1} 个区域` }}</strong><div class="flex gap-2 flex-wrap mt-2"><UButton label="新建场所" icon="i-lucide-plus" :disabled="saving" @click="newPlace" /><UButton v-if="selected" :label="`更新${selected.kind==='point'?'场所位置':'网格边界'}`" variant="outline" :loading="saving" @click="saveShape(selected.kind,selected.id,selected.revision)" /><template v-if="pending.type!=='Point'"><USelect v-model="gridId" :items="grids.filter(x=>x.value!=='all')" placeholder="选择网格" /><UButton label="保存网格边界" color="neutral" variant="outline" :disabled="!gridId||saving" @click="saveShape('grid',gridId,mapState.features.find(x=>x.kind==='grid'&&x.id===gridId)?.revision??0)" /></template></div></div>
    <div v-if="selected && !pending" class="map-pane-stack" :class="{'has-use':useOpen,'has-inspection':!!inspectionId}">
      <div class="map-mobile-tabs floating"><button :class="{active:mobilePane==='place'}" @click="mobilePane='place'">场所信息</button><button v-if="useOpen" :class="{active:mobilePane==='use'}" @click="mobilePane='use'">使用情况</button><button v-if="inspectionId" :class="{active:mobilePane==='inspection'}" @click="mobilePane='inspection'">排查详情</button><UButton icon="i-lucide-x" aria-label="关闭全部详情" color="neutral" variant="ghost" @click="closePlace" /></div>
      <aside class="map-pane floating" :class="{'mobile-active':mobilePane==='place'}" aria-label="场所信息窗"><header><div><small>{{ selected.kind==='grid'?'网格范围':'场所信息' }}</small><h2>{{ selected.icon }} {{ selected.name }}</h2></div><UButton icon="i-lucide-x" aria-label="关闭场所信息" color="neutral" variant="ghost" @click="closePlace" /></header><div class="pane-scroll"><template v-if="detail"><div v-if="detail.photos?.length" class="place-cover"><img :src="`/photos/${detail.photos[0]!.id}?size=thumb`" alt="场所照片" /></div><p>{{ detail.point.address }}</p><p class="text-sm text-muted mt-2">{{ detail.point.communityName }} · {{ detail.point.typeName }}</p><p class="text-sm mt-2">{{ detail.point.contact }} {{ detail.point.phone }}</p><div class="flex gap-2 flex-wrap mt-3"><UButton label="修改场所" size="sm" variant="outline" @click="editingPoint=detail.point;editor=true" /><UButton label="修改区域" size="sm" color="neutral" variant="outline" @click="editShape" /><UButton :to="`/inspections/new?pointId=${selected.id}`" label="登记排查" size="sm" /></div><section class="pane-section"><div class="flex items-center justify-between"><h3>使用情况 <small>{{ shownUses.length }}</small></h3><UButton label="添加" icon="i-lucide-plus" size="sm" variant="ghost" @click="openUse(null)" /></div><UCheckbox v-model="showEnded" label="包括已结束" class="my-2" /><button v-for="item in shownUses" :key="item.id" class="pane-record" :class="{active:useOpen&&useId===item.id}" @click="openUse(item)"><span class="text-2xl">{{ purpose(item.data.purposeId)?.data.icon }}</span><span class="flex-1"><strong>{{ item.name }}</strong><small>{{ item.data.position }} · {{ purpose(item.data.purposeId)?.name }} · {{ item.data.state }}</small></span><UIcon name="i-lucide-chevron-right" /></button><p v-if="!shownUses.length" class="text-sm text-muted py-3">尚未登记使用情况</p></section><section class="pane-section"><h3>排查概览 <small>{{ detail.inspections.length }} 次 · {{ detail.openIssues.length }} 项待完成</small></h3><button v-for="check in detail.inspections" :key="check.id" class="pane-record" :class="{active:inspectionId===check.id}" @click="inspectionId=check.id;mobilePane='inspection'"><span class="flex-1"><strong>{{ check.inspectionTypeName||'日常检查' }}</strong><small>{{ check.date }} · {{ check.useName||'整个场所' }} · {{ check.inspector }}</small></span><UBadge :color="check.result==='normal'?'success':check.result==='incomplete'?'neutral':'warning'" variant="subtle">{{ check.result==='normal'?'正常':check.result==='incomplete'?'未完成':`${check.openIssueCount} 项待办` }}</UBadge></button><p v-if="!detail.inspections.length" class="text-sm text-muted py-3">暂无排查记录</p></section></template><template v-else-if="selected.kind==='grid'"><UButton label="修改网格边界" variant="outline" @click="editShape" /></template><p v-else class="text-muted">正在读取场所…</p></div></aside>
      <aside v-if="useOpen&&detail" class="map-pane floating" :class="{'mobile-active':mobilePane==='use'}" aria-label="使用情况窗"><header><div><small>{{ detail.point.name }}</small><h2>{{ currentUse?'使用情况':'添加用途位置' }}</h2></div><UButton icon="i-lucide-x" aria-label="关闭使用情况" color="neutral" variant="ghost" @click="useOpen=false;mobilePane='place'" /></header><div class="pane-scroll"><UseDetailPanel :key="useId||'new'" :point-id="detail.point.id" :record="currentUse" @saved="useSaved" @cancel="useOpen=false;mobilePane='place'" /></div></aside>
      <aside v-if="inspectionId" class="map-pane floating" :class="{'mobile-active':mobilePane==='inspection'}" aria-label="排查详情窗"><header><h2>排查详情</h2><UButton icon="i-lucide-x" aria-label="关闭排查详情" color="neutral" variant="ghost" @click="inspectionId='';mobilePane='place'" /></header><div class="pane-scroll"><MapInspectionPanel :id="inspectionId" @changed="refreshed" /></div></aside>
    </div>
    <MapLayerControl v-model="mapState.layers" :get-bounds="()=>canvas?.bounds()" />
    <div v-if="!selected&&!pending&&!query" class="map-hint floating">点击场所查看档案，或使用右上角工具标点、画区域</div>
    <PointEditor v-model:open="editor" :point="editingPoint" :initial-coordinates="pendingCoordinates" :initial-shape="pending" @saved="created" />
  </div>
</template>
<style scoped>
.community-map{container-type:inline-size;position:relative;width:100%;height:100%;isolation:isolate;background:#e6e9e5}.floating{background:white;border:1px solid #dfe5e0;border-radius:12px;box-shadow:0 4px 20px #17211e24}.map-search{position:absolute;left:14px;top:14px;width:340px;padding:10px;z-index:12}.map-search-results{max-height:270px;overflow:auto;margin-top:8px}.map-search-results button{display:block;width:100%;padding:9px;text-align:left;border-top:1px solid var(--border)}.map-error{position:absolute;left:370px;right:20px;top:80px;z-index:20}.map-save{position:absolute;bottom:45px;left:50%;transform:translateX(-50%);max-width:calc(100% - 140px);padding:14px;z-index:9}.map-pane-stack{position:absolute;top:78px;left:14px;bottom:34px;z-index:7;display:flex;gap:10px;max-width:calc(100% - 85px);pointer-events:none;align-items:flex-start}.map-pane{width:340px;max-height:100%;display:flex;flex-direction:column;pointer-events:auto;overflow:hidden;flex-shrink:0}.map-pane header{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:14px;border-bottom:1px solid var(--border);flex:none}.map-pane h2{font-size:17px;font-weight:600;line-height:25px}.map-pane header small{font-size:12px;color:var(--text-3)}.pane-scroll{padding:14px;overflow:auto;overscroll-behavior:contain;min-height:0}.place-cover{margin:-14px -14px 12px}.place-cover img{width:100%;max-height:180px;object-fit:cover}.pane-section{border-top:1px solid var(--border);padding-top:14px;margin-top:16px}.pane-section h3{font-weight:600}.pane-section h3 small{color:var(--text-3);font-weight:400}.pane-record{display:flex;align-items:center;gap:10px;width:100%;padding:12px 6px;text-align:left;border-bottom:1px solid var(--border);border-radius:4px}.pane-record strong{display:block;font-weight:500}.pane-record small{display:block;font-size:12px;color:var(--text-3);line-height:20px}.pane-record.active{background:var(--brand-50)}.map-hint{position:absolute;bottom:38px;left:14px;padding:9px 13px;color:var(--text-3);font-size:12px;z-index:3}.map-mobile-tabs{display:none}.map-pane :deep(.detail-grid){grid-template-columns:repeat(2,minmax(0,1fr))}
@media(min-width:901px) and (max-width:1250px){.map-pane{width:290px}.map-pane-stack{gap:6px}.map-pane-stack.has-use.has-inspection .map-pane{width:calc((100cqw - 110px)/3)}}
@media(max-width:900px){.map-search{left:12px;right:12px;width:auto;top:12px}.map-pane-stack{left:12px;right:12px;top:auto;bottom:30px;max-width:none;height:54%;display:flex;flex-direction:column;gap:5px;align-items:stretch}.map-mobile-tabs{display:flex;align-items:center;gap:3px;pointer-events:auto;padding:3px 5px;flex:none}.map-mobile-tabs button{padding:8px 9px;font-size:13px}.map-mobile-tabs button.active{color:var(--brand-700);background:var(--brand-50);border-radius:8px}.map-mobile-tabs :last-child{margin-left:auto}.map-pane{display:none;width:100%;max-height:none;flex:1;min-height:0}.map-pane.mobile-active{display:flex}.map-pane header{padding:9px 12px}.map-pane header h2{font-size:15px}.pane-scroll{padding:12px}.map-save{left:12px;right:12px;transform:none;max-width:none;bottom:34px}.map-error{left:12px;right:12px;top:125px}.map-hint{left:12px;right:100px;bottom:36px;line-height:18px}.map-pane-stack.has-inspection~:deep(.layer-switch){bottom:34px}}
</style>
